const normal = (name, cycleDays, activeDays, seasonal, gestationDays, birthMode, offspringCount, adjustments) => ({
  name,
  system: '普通',
  cycleDays,
  activeDays,
  seasonal,
  defaultOffsetDays: [-2, 2],
  gestationDays,
  birthMode,
  offspringCount,
  adjustments,
});

