const physiology = (sex, capability, classificationId, species, traits) => Object.freeze({
  adult: true,
  sex,
  capability,
  system: classificationId.startsWith('G-M') ? '神话' : '普通',
  classificationId,
  species,
  heritableTraits: Object.freeze(traits),
});

